// Copyright 2026 ReC Sandbox. Scene-referred pipeline, stage S6 (SceneReferredSpec.md).#pragma once//! OpenEXR writer for the scene-referred export tap.//!//! Deliberately NOT part of the stock capture path: `capture_frames`, `RT_ReadTexture`,//! `SCaptureFormatInfo` and `ICaptureFrameListener` are 8-bit by contract and the byte-identity//! harness reads TGA written by exactly that code (research/s6-capture-path.md section 8). This is//! a parallel writer that sits next to WriteTIF and knows nothing about any of it.//!//! Half only. The tap is an fp16 render target, so half is what the data IS: writing float32//! would store fabricated precision at twice the bytes and force a conversion pass that the//! round-trip test then has to account for.#include <CryMath/Cry_Math.h>//! EXR compression codec. Values match TINYEXR_COMPRESSIONTYPE_*, but the enum exists so that//! nothing outside ExrImage.cpp has to include the 10k-line header.enum EExrCompression{	eExrCompression_None = 0,	eExrCompression_RLE  = 1,	eExrCompression_ZIPS = 2,   //!< deflate, one scanline per block	eExrCompression_ZIP  = 3,   //!< deflate, 16 scanlines per block - the CG default	eExrCompression_PIZ  = 4,   //!< wavelet; the ACES container's preference, slow to write};//! One header attribute. Strings and floats and ints are all S6 needs; anything typed (timecode,//! chromaticities) is serialised by the writer itself.struct SExrAttribute{	enum EType	{		eType_String,		eType_Float,		eType_Int,	};	SExrAttribute() : type(eType_String), fValue(0.0f), nValue(0) {}	static SExrAttribute String(const char* szName, const char* szValue)	{		SExrAttribute a;		a.type = eType_String;		a.name = szName;		a.sValue = szValue ? szValue : "";		return a;	}	static SExrAttribute Float(const char* szName, float v)	{		SExrAttribute a;		a.type = eType_Float;		a.name = szName;		a.fValue = v;		return a;	}	static SExrAttribute Int(const char* szName, int v)	{		SExrAttribute a;		a.type = eType_Int;		a.name = szName;		a.nValue = v;		return a;	}	EType  type;	string name;	string sValue;	float  fValue;	int    nValue;};//! Everything about the file that is not its pixels.struct SExrWriteDesc{	SExrWriteDesc()		: compression(eExrCompression_ZIP)		, bWriteAlpha(false)		, bChromaticities(false)		, bAcesImageContainerFlag(false)		, bColorMatrix(false)		, pAttributes(nullptr)		, numAttributes(0)	{		ZeroArray(chromaticities);		ZeroArray(colorMatrix);	}	EExrCompression      compression;	bool                 bWriteAlpha;      //!< false = RGB only, 25 % smaller and the tap's alpha means nothing	//! `chromaticities`, the standard attribute: rx ry gx gy bx by wx wy.	bool                 bChromaticities;	float                chromaticities[8];	//! `acesImageContainerFlag`. ST 2065-4 conformance is a claim about AP0 data; setting it on an	//! AP1 file would be a false claim (research/s6-exr-writer.md section 5.2). The writer does	//! not police it - the capture path decides - but nothing else should ever set it.	bool                 bAcesImageContainerFlag;	//! Optional 3x3 applied to every pixel in float during the de-interleave, row-major. This is	//! how AP1 -> AP0 happens: one matrix on a pass that is already touching every pixel.	bool                 bColorMatrix;	float                colorMatrix[9];	const SExrAttribute* pAttributes;	int                  numAttributes;};//! Writes an interleaved RGBA half image as an OpenEXR file.//! \param szFileName   absolute or pak-relative path; written through ICryPak.//! \param pRGBA        interleaved, 4 halves per texel.//! \param srcRowStrideTexels  texels between the starts of two rows. A mapped staging resource is//!                     PITCHED, not packed - assuming width here is what produces a sheared image.bool WriteEXR(const char* szFileName, int width, int height, const CryHalf* pRGBA, int srcRowStrideTexels, const SExrWriteDesc& desc);//! r_SceneReferredExrSelfTest: write a 4x4 EXR, read it back with tinyexr's own loader and check//! the pixels and the attributes survived. Logs pass/fail. Not a unit-test framework, just the one//! check that says the library is wired up and its custom attributes really reach the file.void ExrSelfTest();